// StaticEmbedding parity against the HuggingFace WordPiece pipeline.
// usage: test_static_embedding <fixture dir with tiny.smstat and cases.tsv>
// The fixture is generated by tests/data/static_fixture/make_fixture.py.

#include <cassert>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <iterator>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

#include "simeon/static_embedding.hpp"

using simeon::StaticEmbedding;

namespace {

std::string unescape(const std::string& s) {
    std::string out;
    for (std::size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '\\' && i + 1 < s.size()) {
            const char c = s[++i];
            out.push_back(c == 't' ? '\t' : c == 'n' ? '\n' : c);
        } else {
            out.push_back(s[i]);
        }
    }
    return out;
}

std::vector<std::string> split(const std::string& s, char sep) {
    std::vector<std::string> out;
    std::string cur;
    for (char c : s) {
        if (c == sep) {
            out.push_back(cur);
            cur.clear();
        } else {
            cur.push_back(c);
        }
    }
    out.push_back(cur);
    return out;
}

int failures = 0;

void check(bool ok, const std::string& what) {
    if (!ok) {
        std::fprintf(stderr, "FAIL: %s\n", what.c_str());
        ++failures;
    }
}

std::vector<std::uint8_t> read_file(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    return {std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>()};
}

bool throws(const std::vector<std::uint8_t>& bytes) {
    try {
        (void)StaticEmbedding::from_bytes(bytes);
    } catch (const std::runtime_error&) {
        return true;
    }
    return false;
}

} // namespace

int main(int argc, char** argv) {
    if (argc < 2) {
        std::fprintf(stderr, "usage: %s <fixture dir>\n", argv[0]);
        return 2;
    }
    const std::string dir = argv[1];
    const auto emb = StaticEmbedding::load(dir + "/tiny.smstat");
    check(emb.dim() == 8, "dim is 8");
    check(emb.vocab_size() > 100, "vocabulary loaded");
    check(emb.unk_id() == 0, "unk id is 0");

    std::ifstream cases(dir + "/cases.tsv");
    std::string line;
    int n = 0;
    while (std::getline(cases, line)) {
        const auto cols = split(line, '\t');
        assert(cols.size() == 3);
        const std::string text = unescape(cols[0]);
        std::vector<std::uint32_t> want_ids;
        std::istringstream ids_in(cols[1]);
        for (std::uint32_t id; ids_in >> id;)
            want_ids.push_back(id);
        std::vector<float> want_vec;
        std::istringstream vec_in(cols[2]);
        for (float v; vec_in >> v;)
            want_vec.push_back(v);

        const auto got_ids = emb.tokenize(text);
        if (got_ids != want_ids) {
            std::string g, w;
            for (auto id : got_ids)
                g += std::to_string(id) + " ";
            for (auto id : want_ids)
                w += std::to_string(id) + " ";
            check(false, "tokenize(\"" + cols[0] + "\") got [" + g + "] want [" + w + "]");
        }
        const auto got_vec = emb.encode(text);
        double dot = 0.0, wn = 0.0, gn = 0.0;
        for (std::size_t d = 0; d < got_vec.size(); ++d) {
            dot += static_cast<double>(got_vec[d]) * want_vec[d];
            wn += static_cast<double>(want_vec[d]) * want_vec[d];
            gn += static_cast<double>(got_vec[d]) * got_vec[d];
        }
        if (wn == 0.0) {
            check(gn == 0.0, "encode(\"" + cols[0] + "\") should be zero");
        } else {
            check(dot / std::sqrt(wn * gn) > 0.9999, "encode(\"" + cols[0] + "\") cosine");
        }
        ++n;
    }
    check(n >= 10, "fixture has cases");

    // Malformed tables are rejected, never read past the end.
    const auto good = read_file(dir + "/tiny.smstat");
    check(!throws(good), "good table loads from bytes");
    auto bad_magic = good;
    bad_magic[0] = 'X';
    check(throws(bad_magic), "bad magic rejected");
    for (std::size_t cut : {std::size_t{4}, std::size_t{20}, good.size() / 2, good.size() - 1})
        check(
            throws(std::vector<std::uint8_t>(good.begin(), good.begin() + static_cast<long>(cut))),
            "truncated table rejected at " + std::to_string(cut));
    auto extra = good;
    extra.push_back(0);
    check(throws(extra), "trailing bytes rejected");

    // Output-size contract.
    std::vector<float> small(3);
    bool threw = false;
    try {
        emb.encode("vitamin", small);
    } catch (const std::invalid_argument&) {
        threw = true;
    }
    check(threw, "encode rejects a wrong output size");

    if (failures == 0)
        std::printf("test_static_embedding: %d cases OK\n", n);
    return failures == 0 ? 0 : 1;
}
